const $=id=>document.getElementById(id),D=OLIST.dimensions,N=new Intl.NumberFormat('en-CA'),money=new Intl.NumberFormat('en-CA',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const fmt=v=>v===null?'N/A':N.format(v),pct=v=>v===null?'N/A':(100*v).toFixed(1)+'%',pretty=s=>s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
let selected=[],stats,metric='low',page=0,queue=[],charts={},active='overview';
Chart.defaults.font.family='Arial, sans-serif';Chart.defaults.font.size=10;Chart.defaults.color='#697d85';Chart.defaults.animation=false;
for(const [id,values] of [['year',[...new Set(D.months.map(m=>m.slice(0,4)))]],['state',D.states],['category',D.categories]])values.forEach((v,i)=>{const o=document.createElement('option');o.value=id==='year'?v:i;o.textContent=id==='category'?pretty(v):v;$(id).append(o);});
function draw(id,type,labels,datasets,extra={}){if(charts[id])charts[id].destroy();charts[id]=new Chart($(id),{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',align:'start',labels:{boxWidth:9,boxHeight:9,padding:15}},tooltip:{padding:11,backgroundColor:'#26373d'}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxRotation:0,autoSkip:true}},y:{beginAtZero:true,grid:{color:'#e5ecee'},border:{display:false}}}},...extra});}
function overview(){const s=stats,groups=s.reviews;$('orders').textContent=fmt(s.orders);$('order-note').textContent=fmt(s.orders-s.eligible)+' excluded from delivery KPIs';$('ontime').textContent=pct(s.onTime);$('eligible-note').textContent=fmt(s.eligible-s.late)+' / '+fmt(s.eligible)+' eligible deliveries';$('p90').textContent=s.p90===null?'N/A':s.p90.toFixed(1)+' days';$('median-note').textContent='Median '+(s.median===null?'N/A':s.median.toFixed(1)+' days');$('low').textContent=pct(groups[1].n?groups[1].low/groups[1].n:null);$('review-note').textContent=fmt(groups[1].low)+' / '+fmt(groups[1].n)+' reviewed late orders';
const months=D.months.filter((m,i)=>selected.some(r=>r[0]===i)),monthly=months.map(m=>Analysis.summarize(selected.filter(r=>D.months[r[0]]===m)));$('period').textContent=months.length?months[0]+' — '+months.at(-1):'No matching orders';
draw('trend','bar',months,[{label:'Eligible deliveries',data:monthly.map(s=>s.eligible),backgroundColor:'#97cccd',borderRadius:2,yAxisID:'y'},{type:'line',label:'Late delivery %',data:monthly.map(s=>s.eligible?100*s.late/s.eligible:null),borderColor:'#c86c5d',backgroundColor:'#c86c5d',pointRadius:2,tension:.2,yAxisID:'rate'}],{options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',align:'start',labels:{boxWidth:9,boxHeight:9}},tooltip:{callbacks:{label:c=>c.dataset.yAxisID==='rate'?c.dataset.label+': '+c.parsed.y.toFixed(1)+'%':c.dataset.label+': '+fmt(c.parsed.y)}}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:8,maxRotation:0}},y:{beginAtZero:true,grid:{color:'#e5ecee'},border:{display:false}},rate:{beginAtZero:true,position:'right',grid:{display:false},ticks:{callback:v=>v+'%'}}}}});
draw('reviews','bar',['On time','Late'],[{label:metric==='low'?'1–2-star reviews (%)':'Average review (/5)',data:groups.map(g=>g.n?(metric==='low'?100*g.low/g.n:g.avg):null),backgroundColor:['#087e83','#cb786b'],borderRadius:3,maxBarThickness:65}],{options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,max:metric==='score'?5:100,grid:{color:'#e5ecee'},ticks:{callback:v=>metric==='low'?v+'%':v}}}}});$('review-caption').textContent='Reviewed eligible orders: '+fmt(groups[0].n)+' on time; '+fmt(groups[1].n)+' late. Missing reviews excluded.';
const states=D.states.map((name,i)=>({name,s:Analysis.summarize(selected.filter(r=>r[1]===i))})).filter(x=>x.s.eligible).sort((a,b)=>b.s.late-a.s.late).slice(0,8);draw('states','bar',states.map(x=>x.name),[{label:'Late orders',data:states.map(x=>x.s.late),backgroundColor:'#087e83',borderRadius:2}],{options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{display:false},tooltip:{callbacks:{afterLabel:c=>'Late rate: '+pct(states[c.dataIndex].s.late/states[c.dataIndex].s.eligible)}}},scales:{x:{beginAtZero:true,grid:{color:'#e5ecee'}},y:{grid:{display:false}}}}});
$('readout-title').textContent=s.eligible?fmt(s.late)+' deliveries missed the promised date.':'No eligible deliveries in this selection.';const diff=groups[0].avg!==null&&groups[1].avg!==null?groups[0].avg-groups[1].avg:null;$('readout').textContent=diff===null?'Review comparison needs reviewed orders in both delivery groups.':`Late deliveries averaged ${groups[1].avg.toFixed(2)}/5 versus ${groups[0].avg.toFixed(2)}/5 on time, a ${Math.abs(diff).toFixed(2)}-point ${diff>=0?'lower':'higher'} score. This is a historical association, not an estimated effect of delivery speed.`;$('gmv').textContent=money.format(s.item);$('freight').textContent=money.format(s.freight);$('missing').textContent=fmt(s.missing)+' orders';}
function sellerTable(){const min=Math.max(1,Number($('minimum').value)||100),search=$('seller-search').value.trim().toLowerCase(),sort=$('sort').value;queue=Analysis.sellers(selected,D,min).filter(x=>x.name.toLowerCase().includes(search)).sort((a,b)=>(sort==='rate'?b.rate-a.rate:sort==='volume'?b.n-a.n:b.late-a.late)||a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(queue.length/20));page=Math.min(page,pages-1);$('seller-count').textContent=fmt(queue.length)+' sellers qualify';$('seller-body').innerHTML=queue.slice(page*20,page*20+20).map(v=>`<tr><td>${v.name}</td><td>${fmt(v.n)}</td><td>${fmt(v.late)}</td><td>${pct(v.rate)}<span class="rate-track"><span style="width:${100*v.rate}%"></span></span></td><td>${v.mean.toFixed(1)}</td><td>${v.avg===null?'N/A':v.avg.toFixed(2)+'/5'}</td><td>${fmt(v.reviewed)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No sellers meet the current filters and minimum volume.</td></tr>';$('page-label').textContent=`Page ${page+1} of ${pages} · ${fmt(queue.length)} sellers`;$('previous').disabled=page===0;$('next').disabled=page===pages-1;}
function update(){selected=Analysis.filter(OLIST.rows,D,{year:$('year').value,state:$('state').value,category:$('category').value});stats=Analysis.summarize(selected);$('scope').textContent=fmt(selected.length)+' orders · '+[$('year').selectedOptions[0].text,$('state').selectedOptions[0].text,$('category').selectedOptions[0].text].join(' / ');if(active==='overview')overview();if(active==='sellers')sellerTable();}
function go(view){active=['overview','sellers','evidence'].includes(view)?view:'overview';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==active);document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===active));history.replaceState(null,'','#'+active);update();window.scrollTo(0,0);}
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('overview');});for(const id of ['year','state','category'])$(id).addEventListener('change',()=>{page=0;update();});$('reset').onclick=()=>{for(const id of ['year','state','category'])$(id).value='';$('seller-search').value='';$('minimum').value=100;$('sort').value='late';page=0;update();};document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;document.querySelectorAll('[data-metric]').forEach(x=>x.classList.toggle('selected',x===b));overview();});for(const id of ['seller-search','minimum','sort'])$(id).addEventListener('input',()=>{page=0;sellerTable();});$('previous').onclick=()=>{page--;sellerTable();};$('next').onclick=()=>{page++;sellerTable();};
$('export').onclick=()=>{const header=['purchase_month','customer_state','category','seller_alias','order_status','delivery_days','late','review_score','item_value_brl','freight_charged_brl'];const lines=[header,...selected.map(r=>[D.months[r[0]],D.states[r[1]],D.categories[r[2]],D.sellers[r[3]],D.statuses[r[4]],r[5],r[6],r[7],(r[8]/100).toFixed(2),(r[9]/100).toFixed(2)])];const csv=lines.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='olist-filtered-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const q=OLIST.quality;$('quality').innerHTML=[['Source orders',q.orders],['Eligible delivered orders',q.eligible_orders],['Delivered but invalid dates',q.delivered_but_ineligible],['Review rows beyond one per order',q.review_rows_beyond_one_per_order],['Multiple-seller orders',q.multi_seller_orders],['Mixed-category orders',q.multi_category_orders],['Item/freight reconciliation','Exact to source cents']].map(([k,v])=>`<div><span>${k}</span><b>${typeof v==='number'?fmt(v):v}</b></div>`).join('');lucide.createIcons();go(location.hash.slice(1)||'overview');
